-- ---------------------------------------------------
-- CHECK CONSTRAINTS
-- ---------------------------------------------------

-- garante a linha única: qualquer outro id_counter é recusado
DO $$
BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_uiclickcounter_single') THEN
		ALTER TABLE tb_ui_click_counter
		ADD CONSTRAINT ck_uiclickcounter_single
		CHECK (id_counter = 1);
	END IF;
END;
$$;

-- ---------------------------------------------------
-- SINGLE ROW
-- ---------------------------------------------------

-- Cria a única linha do contador, com todas as colunas em 0. Reexecutar não zera os contadores.
INSERT INTO tb_ui_click_counter (id_counter)
VALUES (1)
ON CONFLICT (id_counter) DO NOTHING;

-- ---------------------------------------------------
-- UI CLICK VIEWS
-- ---------------------------------------------------

-- Transforma as colunas do contador (uma linha só) em uma linha por elemento clicável.
-- Coluna nova no contador aparece aqui sozinha. platform e type_code saem do nome da coluna
-- (tipo_plataforma_tela_nome); a descrição vem do catálogo de dados. Elemento com 0 cliques
-- aparece com 0 (botão morto). share_pct e rank_in_platform comparam dentro da mesma plataforma.
CREATE OR REPLACE VIEW vw_ui_click_ranking AS
WITH counters AS (
    SELECT
        j.key AS column_name,
        j.value::BIGINT AS clicks
    FROM tb_ui_click_counter c
    CROSS JOIN LATERAL jsonb_each_text(to_jsonb(c) - 'id_counter') AS j
),
base AS (
    SELECT
        c.column_name,
        CASE split_part(c.column_name, '_', 2)
            WHEN 'wb' THEN 'WEB'
            WHEN 'mb' THEN 'MOBILE'
        END AS platform,
        split_part(c.column_name, '_', 1) AS type_code,
        cc.description,
        c.clicks
    FROM counters c
    LEFT JOIN tb_catalog_table t ON t.table_name = 'tb_ui_click_counter'
    LEFT JOIN tb_catalog_column cc ON cc.id_catalog_table = t.id_catalog_table AND cc.column_name = c.column_name
)
SELECT
    b.column_name,
    b.platform,
    b.type_code,
    b.description,
    b.clicks,
    ROUND(100.0 * b.clicks / NULLIF(SUM(b.clicks) OVER (PARTITION BY b.platform), 0), 1) AS share_pct,
    RANK() OVER (PARTITION BY b.platform ORDER BY b.clicks DESC) AS rank_in_platform
FROM base b;

-- ---------------------------------------------------
-- UI CLICK COUNTER METADATA (V014)
-- ---------------------------------------------------

INSERT INTO tb_catalog_table (table_name, domain, description, business_rules, id_access_level, data_owner)
SELECT
	'tb_ui_click_counter', 'EVENT',
	'Contador de cliques: uma linha só, uma coluna por coisa clicável do Inventra (web e mobile).',
	'Linha única (id_counter = 1). Cada clique soma 1 na coluna do elemento (UPDATE ... SET coluna = coluna + 1); não guarda quem clicou nem quando. Campo de digitação e touch de login não têm coluna. Elemento novo = ADD COLUMN em migration nova. Consultada por vw_ui_click_ranking.',
	al.id_access_level, 'Administração do sistema'
FROM tb_catalog_access_level al
WHERE al.code = 'INTERNAL'
ON CONFLICT (table_name) DO UPDATE
SET domain = EXCLUDED.domain,
    description = EXCLUDED.description,
    business_rules = EXCLUDED.business_rules,
    id_access_level = EXCLUDED.id_access_level,
    data_owner = EXCLUDED.data_owner,
    updated_at = CURRENT_TIMESTAMP;

